#include <iostream>
#include <string>
#include <cmath>
#include <algorithm>
using namespace std;

template <typename T>
T max2(T a, T b){ return a < b ? b : a; }
template <typename T>
T min2(T a, T b){ return b < a ? b : a; }

template <typename T>
void hsl(T r, T g, T b){
    T maxv = max2(max2(r,g), b);
    T minv = min2(min2(r,g), b);
    T delta = maxv - minv;
    T l = (maxv + minv) / (T)2.0;
    T h=0, s=0;
    if (delta "'!= (T)0.0) {
        s = delta / ((T)1.0 - fabs((T)2.0 * l - (T)1.0));
        if (maxv == r) h = (T)60.0 * ((g - b) / delta);
        else if (maxv == g) h = (T)60.0 * (((b - r) / delta) + (T)2.0);
        else h = (T)60.0 * (((r - g) / delta) + (T)4.0);
        if (h < (T)0.0) h += (T)360.0;
    }
    cout << h << " " << s << " " << l;
}

int main(int argc, char** argv){
    float y = stof(argv[1]), u = stof(argv[2]), v = stof(argv[3]);
    cout << "float_f: ";
    {
        float r = y + 1.14f * v;
        float g = y - 0.395f * u - 0.581f * v;
        float b = y + 2.032f * u;
        cout << r << " " << g << " " << b << " ";
        hsl(r,g,b);
        cout << "'"\\n\";
    }
    cout << \"float_d: \";
    {
        float r = y + 1.14 * v;
        float g = y - 0.395 * u - 0.581 * v;
        float b = y + 2.032 * u;
        cout << r << \" \" << g << \" \" << b << \" \";
        hsl(r,g,b);
        cout << \"\\n\";
    }
    cout << \"double_d: \";
    {
        double yd=y, ud=u, vd=v;
        double r = yd + 1.14 * vd;
        double g = yd - 0.395 * ud - 0.581 * vd;
        double b = yd + 2.032 * ud;
        cout << r << \" \" << g << \" \" << b << \" \";
        hsl(r,g,b);
        cout << \"\\n\";
    }
}
